from pathlib import Path
import json,hashlib,re,os
from urllib.parse import unquote
R=Path(__file__).resolve().parents[3]
H=R/'astrafinalplan/implementation';B=H/'batch02';D=R.parent;O=R/'astrdocs'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def link(p):return Path(os.path.relpath(p,O)).as_posix().replace(' ','%20')
first=read(H/'delivery-summary.json');second=read(B/'delivery-summary.json');summaries=first+second
courses=read(B/'courses.json');m1=read(H/'delivery-manifest.json');m2=read(B/'delivery-manifest.json')
# Verify this batch against the actual folders before claiming delivery.
for item in m2:
 p=D/item['project']/item['file'];assert p.is_file() and digest(p)==item['after_sha256'],f'Delivery mismatch: {p}'
for item in summaries:
 for p in (D/item['project']/'astraupskill').glob('*.md'):
  prose=re.sub(r'```.*?```','',p.read_text(encoding='utf-8'),flags=re.S)
  for target in re.findall(r'\[[^\]]+\]\(([^)]+)\)',prose):
   if '://' not in target:assert (p.parent/unquote(target.split('#')[0])).resolve().exists(),(p,target)
first_current=[]
for item in m1:
 p=D/item['project']/item['file']
 if not p.exists() or digest(p)!=item['after_sha256']:first_current.append(str(p))
O.mkdir(exist_ok=True)
features=[
'Persistent one-level task undo, including reload and failed-write handling.',
'Case-insensitive duplicate-email validation that permits editing the same contact.',
'Deadline-based countdown, accurate pause/resume and a single completion log.',
'Validated expense editing with stable record identity and persisted totals.',
'Saved shopping quantities, keyboard-editable controls and consistent clipboard output.',
'Validated application JSON export/import with atomic replacement and failure feedback.',
'CRUD regressions, bounded identifiers/titles and unchanged overdue-date editing.',
'Quoted and multiline CSV parsing, complete batch validation and transactional import.',
'Correct category aggregates, month/date filters and amount validation.',
'Owner-scoped updates, strict nested validation and transaction rollback coverage.'
]+[c['after'] for c in courses]
focus=['Undo state and persistence','Normalization and identity','Time and state machines','Editing and derived totals','Accessible controls and saved state','Import boundaries and atomic replacement','HTTP validation and regression tests','Parsing and SQL transactions','SQL aggregates and dates','Ownership and nested transactions']+[c['focus'] for c in courses]
all_docs=sum(x['learning_files'] for x in summaries);all_words=sum(x['learning_words'] for x in summaries);all_tests=sum(x['test_cases'] for x in summaries)
rows=['| Order | Project / course | Implemented improvement | Test cases |','|---|---|---|---:|']
for n,(s,f) in enumerate(zip(summaries,features),1):rows.append(f'| {n} | [{s["project"]}]({link(D/s["project"]/"astraupskill/README.md")}) | {f} | {s["test_cases"]} |')
text=['# All 20 projects: implementation and learning report','','Completed September 8, 2026. The second batch is applied to the ten original Desktop project folders, with detailed junior SWE courses in each project\'s `astraupskill` folder. This report also consolidates the first batch and the earlier inventory/planning work.','','## Delivered totals','',f'- **20 projects** improved across two batches; **{len(m1)+len(m2)} project files** added or changed.',f'- **{all_docs} learning files**, approximately **{all_words:,} words** including executable source and test excerpts.',f'- **{all_tests} automated test cases passed** across the two batches, subject to the first-batch retry detail below.',f'- Second batch: **{len(m2)} files**, **{sum(x["learning_files"] for x in second)} learning files**, **{sum(x["learning_words"] for x in second):,} words**, **21 test cases**, **4 client builds**, **3 TypeScript checks**, **10 Chromium interaction checks**, and a **Knex migration/seed setup check**.','','Word counts describe the delivered material, not a required reading quota. Each course focuses on explaining and independently reproducing one useful engineering improvement.','','## Project-by-project delivery and study order','']+rows+['','The numbering is the agreed first batch followed by the next selected batch. Within the second batch, begin with browser state, filters and date rules, then proceed through file persistence to API/database work. Room Booking is the most demanding second-batch domain exercise; revisit its SQL and timestamp lessons after the simpler browser projects if needed.','','## What each learning folder contains','','Each project has nine Markdown files: a start page; source-linked codebase map; concepts from first principles; worked implementation with concrete input/output examples; testing and debugging; guided and independent practice; separate solutions and review rubric; a trace lab; and verification results. The project root README links the course. Existing Fable and other guides are preserved and linked where applicable.','','The worked changes are implemented. Practice variations are deliberately learner exercises and are not represented as completed features. A useful session is: predict a result, trace the real source, run the focused test, explain the result, then attempt a variation before opening the solution.','','## Earlier review and planning work','','- [Master Desktop review](../astradocs/MASTER_REPORT.md) inventories projects and their SWE learning placement.', '- [Final coverage review](../astradocs/FINAL_REVIEW.md) includes the nested `_Organized Desktop` coverage and discovery exclusions.', '- [Tutorial/codebase explanation report](../astradocs/PROJECT_TUTORIALS_REPORT.md) identifies Fable material and similar guides, including placeholders.', '- [Five-section improvement plan](../astrafinalplan/README.md) covers 389 root records (including 202 organized-subfolder records) plus 75 nested teaching apps: 464 planned entries.', '- [First-ten implementation report](../astrafinalplan/TEN_PROJECTS_IMPLEMENTED.md) retains the first delivery details.','','These inventory counts describe the prior completed review. This turn implemented the next ten; it did not perform another full Desktop scan or claim that every inventoried project was modified. The initial tutorial inventory predates the newly added courses.','','## Verification and limits','','The second batch was tested on isolated working copies, then applied with whole-batch original-file hash checks and per-file post-copy SHA-256 verification. All second-batch delivered hashes and all 20 courses\' local file links were checked in the original folders. '+('The first batch still matches its recorded delivery hashes.' if not first_current else f'{len(first_current)} first-batch files differ from their historical delivery hashes; see the JSON evidence. They were not overwritten.'),'','Second-batch browser checks used actual static apps for the six browser projects. The four React clients were built and exercised with controlled API responses. Their backend suites separately used real HTTP and disposable JSON-file or PostgreSQL persistence. This is not a claim of a deployed end-to-end environment. Metadata fetch tests used a controlled local stub; no external website was fetched.','','First-batch results are historical evidence from the preceding delivery, not freshly rerun in this turn: 116 test cases, six client builds, Recipeweb lint, two Recipe Manager typechecks and six Chromium checks. Daybook passed 89 tests in its full run; the remaining form test passed a focused retry with a 120-second limit. The isolated Vitest worker startup allowance was also extended. Assertions were unchanged.','','The isolated harness used Node 22.16.0 and PostgreSQL 18.1. Development databases, personal saved records and original dependency trees were not used as test fixtures or replaced. The projects still require their documented local dependency/environment setup.','','## Important implemented boundaries','','- Note Vault serializes writes within one repository instance in one process, using temporary-file replacement. It does not provide multi-process locking or guaranteed power-loss durability.', '- Room Booking retains the database exclusion constraint and adds validated edits/time handling. A booked-by label is not authentication or authorization.', '- Notes App now performs English full-text search on the server. Ranking and a GIN index remain future scaling work.', '- Bookmark Manager validates saves separately from optional metadata retrieval. Metadata requires an exact configured host allowlist, defaults disabled, checks DNS and pins the approved address, refuses redirects, and enforces response/time limits. Manual bookmark creation remains available.', '- Browser date/streak improvements do not introduce a continuously scheduled midnight refresh. Budget totals use cents for arithmetic while retaining the existing stored dollar-number schema.','','## Evidence and recovery','','- [Second-batch detailed report](NEXT_10_IMPLEMENTATION_REPORT.md)', '- [Second-batch delivery manifest](../astrafinalplan/implementation/batch02/delivery-manifest.json)', '- [Second-batch automated checks](../astrafinalplan/implementation/batch02/checks.json)', '- [Second-batch browser checks](../astrafinalplan/implementation/batch02/browser-checks.json)', '- [Second-batch source diff](../astrafinalplan/implementation/batch02/source-changes.diff)', '- [Combined machine-readable delivery](all-20-delivery.json)', '', 'Original versions of changed files are retained locally under `astrafinalplan/implementation/backups` for batch one and `astrafinalplan/implementation/batch02/backups` for batch two. New files are identified by a null `before_sha256` in the manifests. Restoring an original file is a deliberate per-file recovery action; the new learning folders can remain.','']
(O/'ALL_20_PROJECTS_REPORT.md').write_text('\n'.join(text),encoding='utf-8')
detail=['# Next ten: implementation details','','Applied September 8, 2026. [Combined report](ALL_20_PROJECTS_REPORT.md).','','This batch follows the first ten with six small browser apps, one file-backed app and three PostgreSQL apps. All listed improvements are installed in the original project folders.']
for i,(s,c) in enumerate(zip(second,courses),11):
 changed=[x['file'] for x in m2 if x['project']==s['project'] and not x['file'].startswith('astraupskill/')]
 detail+=['',f'## {i}. {c["title"]}','',f'[Start the course]({link(D/s["project"]/"astraupskill/README.md")}) | [{s["project"]} verification]({link(D/s["project"]/"astraupskill/VERIFICATION.md")})','',f'**Learning focus:** {c["focus"]}.','',f'**Before:** {c["before"]}','',f'**Implemented:** {c["after"]}','',f'**Concrete example:** {c["example"]}','',f'**Evidence:** {s["test_cases"]} automated test cases; Chromium interaction passed. See the project verification file for its build/typecheck coverage and the distinction between backend persistence tests and client API fixtures.','',f'**Learning material:** {s["learning_files"]} files, approximately {s["learning_words"]:,} words.','', '**Changed or added project files outside the course:**','']+['- '+f'[{p}]({link(D/s["project"]/p)})' for p in changed]
detail+=['','## Final review fixes','','The visual review also corrected the Flashcards checkbox grouping, the Reading List search/filter layout, and Room Booking\'s full-precision date-field layout and display text. Affected browser checks were rerun after those changes. Bookmark Manager also received an explicit TypeScript loader and extension selection for migration/seed commands, plus JSON serialization in the seed. Those commands were checked in a disposable schema.','']
(O/'NEXT_10_IMPLEMENTATION_REPORT.md').write_text('\n'.join(detail),encoding='utf-8')
(O/'README.md').write_text('# Implementation reports\n\nStart with [all 20 projects](ALL_20_PROJECTS_REPORT.md) for everything delivered, course links and verification. [Next-ten details](NEXT_10_IMPLEMENTATION_REPORT.md) covers the latest batch.\n\nThis folder uses the requested spelling `astrdocs`. The earlier inventory and tutorial reports remain in [astradocs](../astradocs/README.md).\n',encoding='utf-8')
(O/'all-20-delivery.json').write_text(json.dumps(dict(date='2026-09-08',projects=summaries,project_files=len(m1)+len(m2),learning_files=all_docs,learning_words=all_words,test_cases=all_tests,second_batch_delivery_verified=True,first_batch_hash_differences=first_current),indent=2),encoding='utf-8')
p=R/'astradocs/README.md';s=p.read_text(encoding='utf-8').replace('No project source was changed.','No project source was changed during that initial inventory review. Subsequent implementation work is recorded in [the all-20 delivery report](../astrdocs/ALL_20_PROJECTS_REPORT.md).');p.write_text(s,encoding='utf-8')
p=R/'astrafinalplan/README.md';s=p.read_text(encoding='utf-8');entry='[All 20 implemented projects and learning courses](../astrdocs/ALL_20_PROJECTS_REPORT.md), including the next-ten delivery.\n\n';s=s.replace('# Astra final improvement plan\n\n','# Astra final improvement plan\n\n'+entry) if entry not in s else s;p.write_text(s,encoding='utf-8')
for p in O.glob('*.md'):
 for target in re.findall(r'\[[^\]]+\]\(([^)]+)\)',p.read_text(encoding='utf-8')):
  assert (p.parent/unquote(target.split('#')[0])).resolve().exists(),(p,target)
(B/'post-apply-verification.json').write_text(json.dumps(dict(second_batch_files_verified=len(m2),learning_links_checked_projects=20,first_batch_hash_differences=first_current,report_links_valid=True),indent=2),encoding='utf-8')
print(json.dumps(dict(report=str(O/'ALL_20_PROJECTS_REPORT.md'),files_verified=len(m2),learning_files=all_docs,learning_words=all_words,tests=all_tests,first_batch_differences=len(first_current)),indent=2))
